    // Clients build rhythm charts and play the spin from shared seeds and constants, so a change to either must raise
    // ProtocolVersion. Each version keeps an immutable recording: add one for a new version and never edit an old one.
    // A version with no recording fails with Record's printout of the current code, ready to paste. Never record an older version.
    public sealed class ProtocolGuardTests
    {
        sealed class StageRecording
        {
            public readonly int Track;public readonly double StartWorldSeconds;public readonly string Kind,Anchor,Chart;
            public StageRecording(int track,double startWorldSeconds,string kind,string anchor,string chart){Track=track;StartWorldSeconds=startWorldSeconds;Kind=kind;Anchor=anchor;Chart=chart;}
        }
        sealed class Recording
        {
            public readonly IReadOnlyList<string> Charts;public readonly string Check,Spin;public readonly IReadOnlyList<StageRecording> Stage;
